<?php
require_once __DIR__ . '/../../includes/db.php';
require_once __DIR__ . '/../includes/auth.php';
require_login();
$result=$conn->query("SELECT c.id,c.car_name,c.plate_number,c.chassis_number,c.purchase_price,c.purchase_date,c.status,IFNULL(cc.total_cost,0) total_cost,cs.sale_price,(IFNULL(cs.sale_price,0)-(c.purchase_price+IFNULL(cc.total_cost,0))) profit,(SELECT r.id FROM reservations r WHERE r.car_id=c.id AND r.status='ACTIVE' AND (r.expiry_date IS NULL OR r.expiry_date>=CURDATE()) ORDER BY r.id DESC LIMIT 1) reservation_id,(SELECT r.customer_name FROM reservations r WHERE r.car_id=c.id AND r.status='ACTIVE' AND (r.expiry_date IS NULL OR r.expiry_date>=CURDATE()) ORDER BY r.id DESC LIMIT 1) reservation_customer FROM cars c LEFT JOIN (SELECT car_id,SUM(amount) total_cost FROM car_costs GROUP BY car_id) cc ON c.id=cc.car_id LEFT JOIN car_sales cs ON c.id=cs.car_id ORDER BY c.created_at DESC");
$cars=$result?$result->fetch_all(MYSQLI_ASSOC):[];$page_title='Cars';include __DIR__.'/../includes/header.php';include __DIR__.'/../includes/leftsidebar.php';
?>
<div class="content-page"><div class="report-title"><h1 class="page-title">Cars</h1><a class="btn btn-green" href="<?=app_url('backend/cars/add.php')?>">Add Car</a></div><div class="card"><div class="filter-bar"><input id="carSearch" placeholder="Search car, plate, chassis"><select id="statusFilter"><option value="">All Statuses</option><option value="IN_STOCK">In Stock</option><option value="SOLD">Sold</option></select><input type="number" id="minPurchase" placeholder="Min purchase"><input type="number" id="maxPurchase" placeholder="Max purchase"><input type="date" id="startDate"><input type="date" id="endDate"></div><div class="table-responsive"><table class="table"><thead><tr><th>Car</th><th>Plate</th><th>Chassis</th><th>Purchase</th><th>Costs</th><th>Sale</th><th>Profit/Loss</th><th>Status</th><th>Date</th><th>Actions</th></tr></thead><tbody><?php if($cars): foreach($cars as $car): $sold=$car['status']==='SOLD'; ?><tr><td data-label="Car"><?=e($car['car_name'])?></td><td data-label="Plate"><?=e(car_sales_plate_label($car['plate_number']))?></td><td data-label="Chassis"><?=e($car['chassis_number'])?></td><td data-label="Purchase"><?=money($car['purchase_price'])?></td><td data-label="Costs"><?=money($car['total_cost'])?></td><td data-label="Sale"><?= $car['sale_price']!==null?money($car['sale_price']):'—' ?></td><td data-label="Profit/Loss"><?= $sold?money($car['profit']):'—' ?></td><td data-label="Status"><span class="badge <?= $sold?'sold':'stock' ?>"><?=e($car['status'])?></span><?php if(!$sold && !empty($car['reservation_id'])):?><br><span class="badge neutral" title="<?=e($car['reservation_customer'])?>">RESERVED</span><?php endif;?></td><td data-label="Date"><?=e($car['purchase_date'])?></td><td><div class="actions"><a class="btn" href="view.php?id=<?=$car['id']?>">View</a><?php if(!$sold):?><a class="btn btn-dark" href="edit.php?id=<?=$car['id']?>">Edit</a><?php endif;?><a class="btn btn-orange" href="../costs/view_cost.php?car_id=<?=$car['id']?>">Costs</a><?php if(!$sold):?><a class="btn btn-green" href="../costs/cost.php?car_id=<?=$car['id']?>">Add Cost</a><a class="btn btn-orange" href="../sales/add.php?car_id=<?=$car['id']?><?=!empty($car['reservation_id'])?'&reservation_id='.(int)$car['reservation_id']:''?>">Sell</a><?php endif;?></div></td></tr><?php endforeach; else: ?><tr><td colspan="10">No cars found.</td></tr><?php endif; ?></tbody></table></div></div></div>
<script>const rows=document.querySelectorAll('tbody tr');function filterTable(){const q=(document.getElementById('carSearch').value||'').toLowerCase();const st=document.getElementById('statusFilter').value;const min=parseFloat(document.getElementById('minPurchase').value);const max=parseFloat(document.getElementById('maxPurchase').value);const s=document.getElementById('startDate').value?new Date(document.getElementById('startDate').value):null;const e=document.getElementById('endDate').value?new Date(document.getElementById('endDate').value):null;rows.forEach(r=>{const txt=r.textContent.toLowerCase();const status=r.querySelector('[data-label="Status"]')?.textContent.trim()||'';const purchase=parseFloat((r.querySelector('[data-label="Purchase"]')?.textContent||'0').replace(/,/g,''));const d=new Date(r.querySelector('[data-label="Date"]')?.textContent||'');const show=txt.includes(q)&&(!st||status.includes(st))&&(isNaN(min)||purchase>=min)&&(isNaN(max)||purchase<=max)&&(!s||d>=s)&&(!e||d<=e);r.style.display=show?'':'none';});}document.querySelectorAll('#carSearch,#statusFilter,#minPurchase,#maxPurchase,#startDate,#endDate').forEach(el=>{el.addEventListener('input',filterTable);el.addEventListener('change',filterTable);});</script>
